import fs from 'node:fs';

const read=p=>fs.readFileSync(p,'utf8');
const write=(p,s)=>fs.writeFileSync(p,s);
function replaceOnce(text,from,to,label){
  const i=text.indexOf(from); if(i<0) throw new Error(`Missing patch target: ${label}`);
  if(text.indexOf(from,i+1)>=0) throw new Error(`Ambiguous patch target: ${label}`);
  return text.slice(0,i)+to+text.slice(i+from.length);
}
function replaceRegex(text,re,to,label){
  const matches=[...text.matchAll(new RegExp(re.source,re.flags.includes('g')?re.flags:re.flags+'g'))];
  if(matches.length!==1) throw new Error(`Expected one ${label} match, found ${matches.length}`);
  return text.replace(re,to);
}
function edit(path,fn){const before=read(path);const after=fn(before);if(after===before)throw new Error(`${path}: patch produced no change`);write(path,after);console.log(`patched ${path}`);}

